import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';
import {bossBrief,bossIntent,bossTarget,bossPhase,bossPresentation,patternGeometry,patternHits,drawPattern} from '../boss-patterns.js';
import {Battle,makeEnemy} from '../battle.js?v=5.6.0';import {defaultHero,compileTechnique} from '../mako.js';
const data=JSON.parse(fs.readFileSync(new URL('../world.json',import.meta.url))),normal=s=>s.toLowerCase().replace(/\s/g,'');
function battle(chapter=1,{context={version:1,tags:[]},heroes=[defaultHero(0,20),defaultHero(1,20),defaultHero(2,20)]}={}){const enemy=makeEnemy('boss',chapter,0,true);enemy.name=bossBrief(chapter).guardian;Object.assign(enemy,{x:10,y:10});heroes.forEach((h,i)=>Object.assign(h,{x:5+i*2,y:9+i*2}));const events=[];return {b:new Battle({chapter,heroes,enemies:[enemy],context,onEvent:e=>events.push(e),rng:()=>.5}),enemy,heroes,events};}

test('guardian identities and readable strategy cards match all 24 actual chapters',()=>{for(const mission of data.campaign.missions){const p=bossBrief(mission.id);assert.equal(normal(p.guardian),normal(mission.enemy_name));assert.equal(p.chapter,mission.id);assert.equal(new Set(p.moves).size,3);assert.equal(new Set(p.sequence).size,3);assert.ok(p.lesson.length>40);assert.ok(['earth','flame','tide','frost','gale','volt','shade','gravity'].includes(p.core));}assert.equal(new Set(data.campaign.missions.map(m=>bossBrief(m.id).name)).size,24);});

test('boss preferences rotate witnesses and select distant, focused or clustered targets deterministically',()=>{const e={x:0,y:0,turn:1},heroes=[{id:0,hp:2,mp:10,x:1,y:1},{id:1,hp:100,mp:30,x:8,y:8},{id:2,hp:100,mp:20,x:9,y:9}];assert.equal(bossTarget(e,2,heroes).id,2);assert.equal(bossTarget(e,5,heroes).id,1);assert.equal(bossTarget(e,3,heroes).id,1);assert.equal(bossTarget(e,1,heroes).id,0);e.turn=2;assert.equal(bossTarget(e,1,heroes).id,1);heroes[1].withdrawn=true;assert.equal(bossTarget(e,5,heroes).id,2);assert.equal(bossTarget(e,1,[]),null);});

test('every move in every phase has bounded power, a safe point and immutable announced geometry',()=>{for(let chapter=1;chapter<=24;chapter++)for(const ratio of [1,.6,.2])for(let turn=1;turn<=3;turn++){const {enemy,heroes}=battle(chapter);enemy.hp=enemy.maxHp*ratio;enemy.turn=turn;const i=bossIntent(enemy,chapter,bossTarget(enemy,chapter,heroes),{heroes});assert.ok(i.left>=2.1);assert.ok(i.power<=enemy.power*1.6);assert.ok(i.recovery>=1.5);assert.ok(i.counterplay.length>15);const before=JSON.stringify(i);for(const h of heroes){h.x+=10;h.y-=10;}assert.equal(JSON.stringify(i),before);let safe=0,unsafe=0;for(let x=0;x<=20;x+=.25)for(let y=0;y<=20;y+=.25){const hit=patternHits(i,{x,y});assert.equal(typeof hit,'boolean');hit?unsafe++:safe++;}assert.ok(safe>0,chapter+':'+i.shape);assert.ok(unsafe>0,chapter+':'+i.shape);}});

test('parallel rails have a genuine central corridor and finite ends, matching their drawn polygons',()=>{const i={shape:'rails',fromX:0,fromY:0,x:6,y:0,width:.55,gap:1.55,endX:9,endY:0};assert.equal(patternHits(i,{x:5,y:0}),false);assert.equal(patternHits(i,{x:5,y:1.55}),true);assert.equal(patternHits(i,{x:5,y:-1.55}),true);assert.equal(patternHits(i,{x:10,y:1.55}),false);assert.equal(patternHits(i,{x:-1,y:1.55}),false);const points=[],ctx={beginPath(){},moveTo(x,y){points.push([x,y]);},lineTo(x,y){points.push([x,y]);},closePath(){},fill(){},stroke(){}};assert.equal(drawPattern(ctx,i,10),true);assert.equal(points.length,8);assert.deepEqual(points[0],[0,-10]);assert.deepEqual(points[1],[90,-10]);assert.ok(points.every(([x,y])=>x>=0&&x<=90&&Math.abs(y)>=10&&Math.abs(y)<=21));});

test('fan and paired circles expose the safe rear and preserve distinct fixed impact areas',()=>{const fan={shape:'cleave',x:10,y:10,heading:0,angle:.62,radius:5.1,inner:.35};assert.equal(patternHits(fan,{x:13,y:10}),true);assert.equal(patternHits(fan,{x:9,y:10}),false);assert.equal(patternHits(fan,{x:10,y:10}),false);assert.equal(patternHits(fan,{x:10,y:13}),false);assert.equal(patternHits(fan,{x:16,y:10}),false);const pair={shape:'pair',x:10,y:10,radius:1.7,points:[{x:7,y:10},{x:13,y:10}]};assert.equal(patternHits(pair,{x:7,y:10}),true);assert.equal(patternHits(pair,{x:13,y:10}),true);assert.equal(patternHits(pair,{x:10,y:10}),false);const calls=[],c=new Proxy({},{get:(_,key)=>(...args)=>calls.push([key,...args])});drawPattern(c,pair,10);assert.deepEqual(calls.filter(a=>a[0]==='arc').map(a=>a.slice(1,4)),[[70,100,17],[130,100,17]]);assert.equal(patternGeometry(fan)[0].kind,'sector');});

test('legacy straight lanes retain their finite hit geometry, and unknown intents stay on the legacy path',()=>{const i={shape:'line',fromX:1,fromY:2,x:7,y:5};for(let x=-2;x<14;x+=.3)for(let y=-2;y<12;y+=.3){const dx=6,dy=3,l=Math.hypot(dx,dy),along=((x-1)*dx+(y-2)*dy)/l,expected=along>=0&&along<=l+3&&Math.abs((x-1)*dy-(y-2)*dx)/l<.85;assert.equal(patternHits(i,{x,y}),expected);}assert.equal(patternHits({shape:'single',x:2,y:2},{x:2,y:2}),null);});

test('phase announcements occur once per threshold and cannot regress after a mender heals the boss',()=>{const {b,enemy,events}=battle(1);b.planEnemy(enemy);assert.equal(events.filter(e=>e.type==='boss-phase').length,0);enemy.hp=enemy.maxHp*.6;enemy.intent=null;b.planEnemy(enemy);assert.equal(events.filter(e=>e.type==='boss-phase').length,1);assert.equal(events.find(e=>e.type==='boss-phase').phase,1);enemy.hp=enemy.maxHp;assert.equal(bossPhase(enemy),1);enemy.intent=null;b.planEnemy(enemy);assert.equal(enemy.phase,1);assert.equal(events.filter(e=>e.type==='boss-phase').length,1);enemy.hp=enemy.maxHp*.2;enemy.intent=null;b.planEnemy(enemy);assert.equal(enemy.phase,2);assert.equal(events.filter(e=>e.type==='boss-phase').length,2);});

test('UI phase stays with an announced move until the next plan and reports actual vulnerability',()=>{const {b,enemy}=battle(8);b.planEnemy(enemy);enemy.hp=enemy.maxHp*.2;let cue=bossPresentation(enemy,8);assert.equal(cue.phaseIndex,0);assert.equal(cue.recovering,false);assert.ok(cue.counterplay);enemy.status.exposed=2;cue=bossPresentation(enemy,8);assert.equal(cue.recoveryLeft,0);enemy.intent=null;enemy.status.stagger=1.5;assert.equal(bossPresentation(enemy,8).recoveryLeft,1.5);enemy.status.stagger=0;b.planEnemy(enemy);assert.equal(bossPresentation(enemy,8).phaseIndex,2);});

test('a completely dodged movement earns a longer real recovery, and Break still cancels every new pattern',()=>{for(const chapter of [2,5,6]){const {b,enemy,heroes,events}=battle(chapter);b.planEnemy(enemy);const i=enemy.intent;for(const h of heroes){h.x=-20;h.y=-20;}b.executeIntent(enemy,i);assert.ok(enemy.status.exposed>=i.recovery+.59);assert.ok(events.some(e=>e.type==='boss-opening'&&e.dodged));enemy.intent=null;b.planEnemy(enemy);const hero=heroes[0];hero.atb=1;hero.mp=hero.maxMp;hero.strain=0;assert.equal(b.command(hero.id,'tech',enemy.id,compileTechnique('earth','break',{character:hero.id})),true);assert.equal(enemy.intent,null);assert.ok(enemy.status.stagger>0);}});

test('boss lightning participates in wet conduction and grounded terrain mitigation through the real damage pipeline',()=>{function strike(wet,tags=[]){const {b,enemy,heroes}=battle(1,{heroes:[defaultHero(0,20)],context:{version:1,tags}});const h=heroes[0];h.x=3;h.y=3;if(wet)h.status.wet=5;enemy.hp=enemy.maxHp*.5;enemy.turn=0;b.planEnemy(enemy);const i=enemy.intent;assert.equal(i.core,'volt');assert.equal(i.shape,'burst');const before=h.hp;b.executeIntent(enemy,i);return before-h.hp;}const dry=strike(false),wet=strike(true),grounded=strike(false,['grounded']);assert.ok(wet>dry);assert.ok(grounded<dry);});

test('all new pattern geometry and phase progress roundtrip battle snapshots without recalculation',()=>{for(const chapter of [2,3,5,6,8,24]){const {b,enemy}=battle(chapter);enemy.hp=enemy.maxHp*.2;enemy.turn=1;b.planEnemy(enemy);const snapshot=b.snapshot(),intent=JSON.stringify(enemy.intent);b.restore(snapshot);assert.equal(JSON.stringify(b.enemies[0].intent),intent);assert.equal(b.enemies[0].phase,2);assert.deepEqual(b.snapshot().enemies[0],snapshot.enemies[0]);}});
